'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var dmskmaxabs = require( './../lib' );


// TESTS //

tape( 'main export is an object', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dmskmaxabs, 'object', 'main export is an object' );
	t.end();
});

tape( 'the `main` method has an arity of 5', function test( t ) {
	t.strictEqual( dmskmaxabs.main.length, 5, 'returns expected value' );
	t.end();
});

tape( 'the `main` method computes the maximum absolute value of a strided array according to a mask', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
	mask = new Uint8Array( [ 0, 0, 1, 0 ] );

	v = dmskmaxabs.main( x.length, x, 1, mask, 1 );
	t.strictEqual( v, 2.0, 'returns expected value' );

	x = new Float64Array( [ -4.0, NaN, -5.0 ] );
	mask = new Uint8Array( [ 0, 1, 0 ] );

	v = dmskmaxabs.main( x.length, x, 1, mask, 1 );
	t.strictEqual( v, 5.0, 'returns expected value' );

	t.end();
});

tape( 'the `main` method supports an `x` stride', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		2.0,  // 0
		-3.0,
		-5.0, // 1
		7.0,
		6.0   // 2
	]);
	mask = new Uint8Array([
		0, // 0
		1, // 1
		0  // 2
	]);

	v = dmskmaxabs.main( 3, x, 2, mask, 1 );
	t.strictEqual( v, 6.0, 'returns expected value' );
	t.end();
});

tape( 'the `main` method supports a `mask` stride', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		2.0,  // 0
		-3.0, // 1
		-5.0  // 2
	]);
	mask = new Uint8Array([
		0, // 0
		1,
		0, // 1
		1,
		0  // 2
	]);

	v = dmskmaxabs.main( 3, x, 1, mask, 2 );
	t.strictEqual( v, 5.0, 'returns expected value' );
	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the `main` method returns `NaN`', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array( [ 3.0, -4.0, 1.0 ] );
	mask = new Uint8Array( [ 0, 0, 0 ] );

	v = dmskmaxabs.main( 0, x, 1, mask, 1 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = dmskmaxabs.main( -4, x, 1, mask, 1 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the `main` method supports negative strides', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		1.0, // 2
		2.0,
		3.0, // 1
		4.0,
		5.0  // 0
	]);
	mask = new Uint8Array([
		0, // 2
		1, // 1
		0  // 0
	]);

	v = dmskmaxabs.main( 3, x, -2, mask, -1 );
	t.strictEqual( v, 5.0, 'returns expected value' );
	t.end();
});

tape( 'the `main` method supports view offsets', function test( t ) {
	var mask0;
	var mask1;
	var x0;
	var x1;
	var v;

	x0 = new Float64Array([
		2.0,
		1.0,  // 0
		-2.0,
		-2.0, // 1
		3.0,
		4.0,  // 2
		5.0,
		6.0   // 3
	]);
	mask0 = new Uint8Array([
		0,
		0, // 0
		0,
		0, // 1
		0,
		0, // 2
		1,
		1  // 3
	]);

	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );
	mask1 = new Uint8Array( mask0.buffer, mask0.BYTES_PER_ELEMENT*1 );

	v = dmskmaxabs.main( 4, x1, 2, mask1, 2 );
	t.strictEqual( v, 4.0, 'returns expected value' );
	t.end();
});
